305	  server.listen(port, () => { console.log('Backend listening at http://127.0.0.1:' + port); });
306	});

  1	// Locator helpers for generated acceptance tests. Names are matched exactly (case-insensitive,
  2	// whitespace-tolerant) and must resolve to ONE visible element: duplicates are reported as
  3	// failures because independent acceptance tests commonly use strict locators.
  4	import { expect, Locator, Page } from '@playwright/test';
  5	
  6	export type Scope = Page | Locator;
  7	
  8	export function escapeRegExp(text: string): string {
  9	  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
 10	}
 11	
 12	/** Exact accessible-name matcher: /^\s*name\s*$/i with flexible inner whitespace. */
 13	export function exact(name: string | RegExp): RegExp {
 14	  if (name instanceof RegExp) return name;
 15	  return new RegExp('^\\s*' + escapeRegExp(name.trim()).replace(/\s+/g, '\\s+') + '\\s*$', 'i');
 16	}
 17	
 18	/** Substring matcher for visible text content. */
 19	export function contains(text: string | RegExp): RegExp {
 20	  if (text instanceof RegExp) return text;
 21	  return new RegExp(escapeRegExp(text.trim()).replace(/\s+/g, '\\s+'), 'i');
 22	}
 23	
 24	const CLICKABLE = ['button', 'link', 'menuitem', 'tab', 'option', 'checkbox', 'radio', 'switch', 'treeitem', 'menuitemcheckbox', 'menuitemradio'] as const;
 25	// Named, clickable-in-practice elements that are not "controls" in ARIA terms: grid/table cells and headers
 26	// (e.g. a grid cell named by its coordinate) and list rows. Checked only after the control roles.
 27	const NAMED_ITEMS = ['gridcell', 'cell', 'columnheader', 'rowheader', 'row', 'listitem'] as const;
 28	const FIELDS = ['textbox', 'searchbox', 'combobox', 'spinbutton'] as const;
 29	
 30	async function single(candidates: Locator[], what: string): Promise<Locator> {
 31	  const deadline = Date.now() + 5000;
 32	  let lastCounts = '';
 33	  while (true) {
 34	    const counts: number[] = [];
 35	    for (const candidate of candidates) {
 36	      const visible = candidate.filter({ visible: true });
 37	      const count = await visible.count().catch(() => 0);
 38	      counts.push(count);
 39	      if (count === 1) return visible;
 40	      if (count > 1) throw new Error(`Ambiguous ${what}: ${count} visible elements match; names must be unique on the page`);
 41	    }
 42	    lastCounts = counts.join(',');
 43	    if (Date.now() > deadline) break;
 44	    await new Promise((resolve) => setTimeout(resolve, 150));
 45	  }
 46	  throw new Error(`Not found: ${what} (no visible element; candidate counts ${lastCounts})`);
 47	}
 48	
 49	/** A clickable control by exact accessible name (button, link, tab, menu item, ...), a named grid/table cell or
 50	 *  list item (e.g. a cell named "A1"), or exact visible text. */
 51	export async function control(scope: Scope, name: string | RegExp): Promise<Locator> {
 52	  const pattern = exact(name);
 53	  const s = scope as any;
 54	  return single([...CLICKABLE.map((role) => s.getByRole(role, { name: pattern })),
 55	                 ...NAMED_ITEMS.map((role) => s.getByRole(role, { name: pattern })),
 56	                 s.getByText(pattern)], `control ${pattern}`);
 57	}
 58	
 59	export async function click(scope: Scope, name: string | RegExp): Promise<void> {
 60	  await (await control(scope, name)).click();
 61	}
 62	
 63	/** A form field by exact label, placeholder or accessible name. */
 64	export async function field(scope: Scope, label: string | RegExp): Promise<Locator> {
 65	  const pattern = exact(label);
 66	  const s = scope as any;
 67	  return single([s.getByLabel(pattern), s.getByPlaceholder(pattern), ...FIELDS.map((role) => s.getByRole(role, { name: pattern }))], `field ${pattern}`);
 68	}
 69	
 70	export async function fill(scope: Scope, label: string | RegExp, value: string): Promise<void> {
 71	  await (await field(scope, label)).fill(value);
 72	}
 73	
 74	export async function select(scope: Scope, label: string | RegExp, option: string): Promise<void> {
 75	  const element = await field(scope, label);
 76	  const tag = await element.evaluate((node) => node.tagName.toLowerCase());
 77	  if (tag === 'select') {
 78	    await element.selectOption({ label: option });
 79	    return;
 80	  }
 81	  await element.click();
 82	  const page: Page = typeof (scope as any).page === 'function' ? (scope as Locator).page() : (scope as Page);
 83	  await click(page, option);
 84	}
 85	
 86	/** Assert some visible element shows this text (substring, case-insensitive unless a RegExp is given). */
 87	export async function expectText(scope: Scope, text: string | RegExp): Promise<void> {
 88	  await expect((scope as any).getByText(contains(text)).filter({ visible: true }).first()).toBeVisible();
 89	}
 90	
 91	export async function expectNoText(scope: Scope, text: string | RegExp): Promise<void> {
 92	  await expect((scope as any).getByText(contains(text)).filter({ visible: true })).toHaveCount(0);
 93	}
 94	
 95	/** A landmark/container by role and exact name, e.g. region('dialog', 'Create item'). */
 96	export function region(scope: Scope, role: string, name?: string | RegExp): Locator {
 97	  return (scope as any).getByRole(role, name === undefined ? {} : { name: exact(name) });
 98	}
 99	
100	/** A grid/table cell by its accessible name (e.g. a grid cell named by its coordinate "A1"). */
101	export function cell(scope: Scope, name: string | RegExp): Locator {
102	  const s = scope as any;
103	  return s.getByRole('gridcell', { name: exact(name) }).or(s.getByRole('cell', { name: exact(name) }));
104	}
105	
106	/** The row/article/listitem that contains the given text. */
107	export function itemWith(scope: Scope, role: 'row' | 'article' | 'listitem' | 'option' | 'gridcell' | 'cell', text: string | RegExp): Locator {
108	  return (scope as any).getByRole(role).filter({ hasText: contains(text) });
109	}
  1	// Drop-in replacement for '@playwright/test' in generated specs: on failure it attaches the
  2	// page URL, an accessibility snapshot and browser errors so repairs see what the test saw.
  3	import { test as base } from '@playwright/test';
  4	export * from '@playwright/test';
  5	
  6	export const test = base.extend<{ evogitCapture: void }>({
  7	  evogitCapture: [async ({ page }, use, testInfo) => {
  8	    // Start every test from the seeded state (local runs only; ignored when the host has no reset endpoint).
  9	    if (process.env.EVOGIT_RESET === '1' && process.env.EVOGIT_BASE_URL) {
 10	      try { await fetch(process.env.EVOGIT_BASE_URL + '/api/__evogit_reset', { method: 'POST' }); } catch { /* ignore */ }
 11	    }
 12	    const errors: string[] = [];
 13	    page.on('pageerror', (error) => errors.push(String((error as Error).message || error).slice(0, 400)));
 14	    page.on('console', (message) => { if (message.type() === 'error') errors.push('console: ' + message.text().slice(0, 300)); });
 15	    page.on('response', (response) => {
 16	      const status = response.status();
 17	      if (status >= 400 && status !== 401 && response.url().includes('/api/') && errors.length < 40)
 18	        errors.push(`HTTP ${status} ${response.request().method()} ${new URL(response.url()).pathname}`);
 19	    });
 20	    await use();
 21	    if (testInfo.status !== testInfo.expectedStatus) {
 22	      let aria = '';
 23	      try { aria = await page.locator('body').ariaSnapshot({ timeout: 2000 }); } catch { aria = ''; }
 24	      await testInfo.attach('evogit-failure', {
 25	        body: JSON.stringify({ url: page.url(), aria: aria.slice(0, 6000), errors: errors.slice(0, 12) }),
 26	        contentType: 'application/json',
 27	      });
 28	    }
 29	  }, { auto: true }],
 30	});
